mapper.select:
SELECT run_id,question,answer,required_tools FROM supervisor_conversations
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND session_id=#{sessionId}
ORDER BY sequence_id

SELECT memory_key,memory_value,version,source,expires_at FROM supervisor_memories
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND deleted=FALSE
  AND expires_at>#{now} AND memory_key>#{after}
ORDER BY memory_key LIMIT #{limit}

SELECT * FROM supervisor_memory_candidates
WHERE tenant_id=#{tenantId} AND user_id=#{userId}
ORDER BY requested_at DESC LIMIT 200

mapper.update:
UPDATE supervisor_memory_vectors SET deleted=TRUE,vector_json='[]'
WHERE deleted=FALSE AND memory_key IN (
  SELECT memory_key FROM supervisor_memories WHERE deleted=TRUE OR expires_at<=#{now}
)
